@js:
//eval(String(source.bookSourceComment));

list=[]
lis=result
for(i in lis){
if(String(lis[i]).match(/bar/)){
		  list.push({
				text: " 🏷️["+lis[i].text()+"] ",
				vo: true
			});
	}
else{
		lis[i].select("a").forEach(a=>{
				list.push({
						text: a.text(),
						href: a.attr("href")
					})
			})
	}
}
list

